---@class PlayerSampleInfoData PlayerSampleInfoData
PlayerSampleInfoData = class("PlayerSampleInfoData")

function PlayerSampleInfoData:initialize()
    self.roleName = "" --玩家名称
    self.bgIcon = ""  --背景条
    self.isDynamicBg = false
    self.headIcon = "" --头像
    self.iconFrame = ""--边框
    self.level = -1--等级
    self.cups = {}
end

---@param clone PlayerData
function PlayerSampleInfoData:Clone(clone)
    clone.roleName = self.roleName --玩家名称
    clone.bgIcon = self.bgIcon  --背景条
    clone.isDynamicBg = self.isDynamicBg --是否是动态背景
    clone.headIcon = self.headIcon --头像
    clone.level = self.level--等级
    clone.iconFrame = self.iconFrame--边框
    clone.cups = { [1] = self.cups[1], [2] = self.cups[2], [3] = self.cups[3] }
end

---@param playerData PlayerData
function PlayerSampleInfoData:SetDataByPlayerData(playerData)

    self.roleName = playerData.roleName --玩家名称
    self.level = tonumber( playerData.curLevel)--等级
    self.cups = { [1] = playerData.cups[1], [2] = playerData.cups[2], [3] = playerData.cups[3] }

    self:SetHeadIcon(playerData.headIcon)

    self:SetIconFrame(playerData.iconFrame)

    self:SetBgId(playerData.background)
end
---@param carDyData CarDyData
function PlayerSampleInfoData:SetDataByCarDyData(carDyData)
    self.roleName = carDyData.playerName --玩家名称
    self:SetBgId(carDyData.playerBgId)   --背景条
    self.headIcon=carDyData.playerHeadIcon--头像
    self.level = tonumber(carDyData.playerLevel)--等级
    self.iconFrame = carDyData.playerIconFrame--边框
    self.cups = carDyData.cups
    self.background = carDyData.background
end

function PlayerSampleInfoData:SetRoleName(roleName)
    self.roleName = roleName --玩家名称
end

function PlayerSampleInfoData:SetBgId(bgId)
    self.bgIcon = "playerbg_z_default.png"
    self.isDynamicBg = false
    ---@type dictarticle_config_cell
    local cfgArticle = CommonHelper:GetTableDataByID(ConfigNames.article_config, bgId)
    if cfgArticle then
        ---@type dictheadicon_config_cell
        local cfgBgIcon = CommonHelper:GetTableDataByID(ConfigNames.headicon_config, cfgArticle.propsadd)
        if cfgBgIcon then
            local list = stringSplit(cfgBgIcon.icon, '_')
            self.isDynamicBg = list[1] == "prefab"
            self.bgIcon = self.isDynamicBg and cfgBgIcon.icon or string.format("%s.png", cfgBgIcon.icon)
        end
    end
end

function PlayerSampleInfoData:SetHeadIcon(headIconId)
    self.headIcon = "playericon_z_default.png"
    local cfgIcon = CommonHelper:GetTableDataByID(ConfigNames.headicon_config, headIconId)
    if cfgIcon then
        local hero_config_cell = CommonHelper:GetTableDataByID(ConfigNames.hero_config, tonumber(cfgIcon.icon))
        if hero_config_cell then
            self.headIcon = hero_config_cell.NewIcon--头像
        end
    end
end

function PlayerSampleInfoData:SetIconFrame(iconFrameId)
    self.iconFrame = "player_kuangicon_1.png"
    ---@type dictheadicon_config_cell
    local cfgFrame = CommonHelper:GetTableDataByID(ConfigNames.headicon_config, iconFrameId)
    if cfgFrame then
        self.iconFrame = string.format("%s.png", cfgFrame.icon)
    end
end

function PlayerSampleInfoData:SetLevel(level)
    self.level = tonumber(level) --等级
end

function PlayerSampleInfoData:SetCup(cups)
    self.cups = { [1] = cups[1], [2] = cups[2], [3] = cups[3] }
end

---@class PlayerSampleInfoDataManager
PlayerSampleInfoDataManager = class("PlayerSampleInfoDataManager")

function PlayerSampleInfoDataManager:initialize()
    self.PlayerSampleInfoData = PlayerSampleInfoData()
end

---@return PlayerSampleInfoDataManager
function PlayerSampleInfoDataManager:Get()
    if self._instance == nil then
        self._instance = PlayerSampleInfoDataManager()
    end
    return self._instance
end

function PlayerSampleInfoDataManager:GetSelfSampleInfo()
    return self.PlayerSampleInfoData
end